import{_ as l,a0 as p,w as d,s as o,ao as r,I as n,x as a,a1 as e,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"在 Linux 中創建 LVM 分區的分步指南 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 中創建 LVM 分區的分步指南 | LCTT (202210) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 中創建 LVM 分區的分步指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 中創建 LVM 分區的分步指南 | LCTT (202210) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202210/20221008 How to Create LVM Partition Step-by-Step in Linux","title":"在 Linux 中創建 LVM 分區的分步指南","tag":"202210","desc":""},"relativePath":"202210/20221008 How to Create LVM Partition Step-by-Step in Linux.md","filePath":"[post].md"}'),h={name:"202210/20221008 How to Create LVM Partition Step-by-Step in Linux.md"};function c(g,s,u,k,b,m){const i=p("Link");return d(),o("div",null,[s[15]||(s[15]=r(`<h1 id="在-linux-中創建-lvm-分區的分步指南" tabindex="-1">在 Linux 中創建 LVM 分區的分步指南 <a class="header-anchor" href="#在-linux-中創建-lvm-分區的分步指南" aria-label="Permalink to “在 Linux 中創建 LVM 分區的分步指南”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202210/18/113615swffwazya3nyfve2.jpg" alt=""></p><blockquote><p>在本指南中，我們將逐步介紹如何在 Linux 中創建 LVM 分區。</p></blockquote><p>LVM 代表 “<ruby>邏輯卷管理<rt>Logical Volume Management</rt></ruby>”，它是專門為服務器管理 Linux 系統上的磁盤或存儲的推薦方式。 LVM 分區的主要優點之一是我們可以實時擴展其大小而無需停機。 LVM 分區也可以縮小，但不推薦。</p><p>為了演示，我在我的 Ubuntu 22.04 系統上連接了 15GB 磁盤，我們將從命令列在該磁盤上創建 LVM 分區。</p><h5 id="準備" tabindex="-1">準備 <a class="header-anchor" href="#準備" aria-label="Permalink to “準備”">​</a></h5><ul><li>連接到 Linux 系統的原始磁盤</li><li>具有 sudo 權限的本地用户</li><li>預裝 lvm2 包</li></ul><p>事不宜遲，讓我們深入瞭解這些步驟。</p><h3 id="步驟-1、識別新連接的原始磁盤" tabindex="-1">步驟 1、識別新連接的原始磁盤 <a class="header-anchor" href="#步驟-1、識別新連接的原始磁盤" aria-label="Permalink to “步驟 1、識別新連接的原始磁盤”">​</a></h3><p>登錄到你的系統，打開終端並運行以下 <code>dmesg</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dmesg | grep -i sd</span></span></code></pre></div><p>在輸出中，查找大小為 15GB 的新磁盤。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/10/dmesg-command-new-attached-disk-linux.png" alt="dmesg-command-new-attached-disk-linux"></p><p>識別新連接的原始磁盤的另一種方法是通過 <code>fdisk</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo fdisk -l | grep -i /dev/sd</span></span></code></pre></div><p>輸出：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/10/fdisk-command-output-new-disk.png" alt="fdisk-command-output-new-disk"></p><p>從上面的輸出，可以確認新連接的磁盤是 <code>/dev/sdb</code>。</p><h3 id="步驟-2、創建-pv-物理卷" tabindex="-1">步驟 2、創建 PV（物理卷） <a class="header-anchor" href="#步驟-2、創建-pv-物理卷" aria-label="Permalink to “步驟 2、創建 PV（物理卷）”">​</a></h3><p>在開始在磁盤 <code>/dev/sdb</code> 上創建<ruby>物理卷<rt>Physical Volume</rt></ruby>（PV）之前，請確保已安裝 <code>lvm2</code> 包。如果未安裝，請運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install lvm2     // On Ubuntu / Debian</span></span>
<span class="line"><span>$ sudo dnf install lvm2    // on RHEL / CentOS</span></span></code></pre></div><p>運行以下 <code>pvcreate</code> 命令在磁盤 <code>/dev/sdb</code> 上創建 PV：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pvcreate /dev/sdb</span></span>
<span class="line"><span>  Physical volume &quot;/dev/sdb&quot; successfully created.</span></span>
<span class="line"><span>$</span></span></code></pre></div><p>要驗證 PV 狀態，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pvs /dev/sdb</span></span>
<span class="line"><span>或者</span></span>
<span class="line"><span>$ sudo pvdisplay /dev/sdb</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/10/pvdisplay-command-output-linux.png" alt="pvdisplay-command-output-linux"></p><h3 id="步驟-3、創建-vg-卷組" tabindex="-1">步驟 3、創建 VG（卷組） <a class="header-anchor" href="#步驟-3、創建-vg-卷組" aria-label="Permalink to “步驟 3、創建 VG（卷組）”">​</a></h3><p>要創建<ruby>卷組<rt>Volume Group</rt></ruby>（VG），我們將使用 <code>vgcreate</code> 命令。創建 VG 意味着將 PV 添加到其中。</p><p>語法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vgcreare &lt;vg_name&gt;  &lt;pv&gt;</span></span></code></pre></div><p>在我們的例子中，命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vgcreate volgrp01 /dev/sdb</span></span>
<span class="line"><span>  Volume group &quot;volgrp01&quot; successfully created</span></span>
<span class="line"><span>$</span></span></code></pre></div><p>運行以下命令以驗證 VG（<code>volgrp01</code>）的狀態：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vgs volgrp01</span></span>
<span class="line"><span>或者</span></span>
<span class="line"><span>$ sudo vgdisplay volgrp01</span></span></code></pre></div><p>上述命令的輸出：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/10/vgs-command-output-linux.png" alt="vgs-command-output-linux"></p><p>以上輸出確認大小為 15 GiB 的卷組 <code>volgrp01</code> 已成功創建，一個<ruby>物理擴展<rt>Physical Extend</rt></ruby>（PE）的大小為 4 MB。創建 VG 時可以更改 PE 大小。</p><h3 id="步驟-4、創建-lv-邏輯卷" tabindex="-1">步驟 4、創建 LV（邏輯卷） <a class="header-anchor" href="#步驟-4、創建-lv-邏輯卷" aria-label="Permalink to “步驟 4、創建 LV（邏輯卷）”">​</a></h3><p><code>lvcreate</code> 命令用於從 VG 中創建<ruby>邏輯卷<rt>Logical Volume</rt></ruby> LV。 <code>lvcreate</code> 命令的語法如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lvcreate -L &lt;Size-of-LV&gt; -n &lt;LV-Name&gt;   &lt;VG-Name&gt;</span></span></code></pre></div><p>在我們的例子中，以下命令將用於創建大小為 14 GB 的 LV：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lvcreate -L 14G -n lv01 volgrp01</span></span>
<span class="line"><span>  Logical volume &quot;lv01&quot; created.</span></span>
<span class="line"><span>$</span></span></code></pre></div><p>驗證 LV 的狀態，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lvs /dev/volgrp01/lv01</span></span>
<span class="line"><span>或者</span></span>
<span class="line"><span>$ sudo lvdisplay /dev/volgrp01/lv01</span></span></code></pre></div><p>輸出：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/10/lvs-command-output-linux.png" alt="lvs-command-output-linux"></p><p>上面的輸出顯示 LV（<code>lv01</code>）已成功創建，大小為 14 GiB。</p><h3 id="步驟-5、格式化-lvm-分區" tabindex="-1">步驟 5、格式化 LVM 分區 <a class="header-anchor" href="#步驟-5、格式化-lvm-分區" aria-label="Permalink to “步驟 5、格式化 LVM 分區”">​</a></h3><p>使用 <code>mkfs</code> 命令格式化 LVM 分區。在我們的例子中，LVM 分區是 <code>/dev/volgrp01/lv01</code>。</p><p>注意：我們可以將分區格式化為 ext4 或 xfs，因此請根據你的設置和要求選擇文件系統類型。</p><p>運行以下命令將 LVM 分區格式化為 ext4 文件系統。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkfs.ext4 /dev/volgrp01/lv01</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/10/mkfs-ext4-filesystem-lvm.png" alt="mkfs-ext4-filesystem-lvm"></p><p>執行下面的命令，用 xfs 文件系統格式化 LVM 分區：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkfs.xfs /dev/volgrp01/lv01</span></span></code></pre></div><p>要使用上述格式化分區，我們必須將其掛載到某個文件夾中。所以，讓我們創建一個文件夾 <code>/mnt/data</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkdir /mnt/data</span></span></code></pre></div><p>現在運行 <code>mount</code> 命令將其掛載到 <code>/mnt/data</code> 文件夾：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mount /dev/volgrp01/lv01 /mnt/data/</span></span>
<span class="line"><span>$ df -Th /mnt/data/</span></span>
<span class="line"><span>Filesystem                Type  Size  Used Avail Use% Mounted on</span></span>
<span class="line"><span>/dev/mapper/volgrp01-lv01 ext4   14G   24K   13G   1% /mnt/data</span></span>
<span class="line"><span>$</span></span></code></pre></div><p>嘗試創建一些沒用的文件，運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd /mnt/data/</span></span>
<span class="line"><span>$ echo &quot;testing lvm partition&quot; | sudo tee dummy.txt</span></span>
<span class="line"><span>$ cat dummy.txt</span></span>
<span class="line"><span>testing lvm partition</span></span>
<span class="line"><span>$</span></span>
<span class="line"><span>$ sudo rm -f  dummy.txt</span></span></code></pre></div><p>完美，以上命令輸出確認我們可以訪問 LVM 分區。</p><p>要永久掛載上述 LVM 分區，請使用以下 <code>echo</code> 命令將其條目添加到 <code>fstab</code> 文件中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &#39;/dev/volgrp01/lv01  /mnt/data  ext4  defaults 0 0&#39; | sudo  tee -a /etc/fstab</span></span>
<span class="line"><span>$ sudo mount -a</span></span></code></pre></div><p>以上就是本指南的全部內容，感謝閲讀。請在下面的評論區發表你的問題和反饋。</p><hr>`,66)),n("p",null,[s[1]||(s[1]=a("via: ",-1)),e(i,{href:"https://www.linuxtechi.com/how-to-create-lvm-partition-in-linux/"},{default:t(()=>[...s[0]||(s[0]=[a("https://www.linuxtechi.com/how-to-create-lvm-partition-in-linux/",-1)])]),_:1})]),n("p",null,[s[6]||(s[6]=a("作者：",-1)),e(i,{href:"https://www.linuxtechi.com/author/james/"},{default:t(()=>[...s[2]||(s[2]=[a("James Kiarie",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),e(i,{href:"https://github.com/lkxed"},{default:t(()=>[...s[3]||(s[3]=[a("lkxed",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),e(i,{href:"https://github.com/geekpi"},{default:t(()=>[...s[4]||(s[4]=[a("geekpi",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),e(i,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),e(i,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[a("Linux 中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const y=l(h,[["render",c]]);export{x as __pageData,y as default};
